func outer(_ x: Int) -> Int {
    func inner(_ y: Int) -> Int {
        return y * 2
    }
    return inner(x) + 1
}

func minMax(_ xs: [Int]) -> (Int, Int) {
    return (xs.min() ?? 0, xs.max() ?? 0)
}

func process(_ maybe: Int?) -> Int {
    if let v = maybe {
        return v * 2
    }
    return 0
}

func area(_ s: Shape) -> Double {
    switch s {
    case .circle(let r):
        return 3.14159 * r * r
    case .rect(let w, let h):
        return w * h
    }
}

func zeros(_ n: Int) -> [Int] {
    return Array(repeating: 0, count: n)
}

func concat(_ xs: [String]) -> String {
    var result = ""
    for x in xs {
        result += x
    }
    return result
}

func sum1toN(_ n: Int) -> Int {
    var total = 0
    for i in 1...n {
        total += i
    }
    return total
}

func indices(_ n: Int) -> [Int] {
    return Array(0..<n)
}

func parse(_ s: String) throws -> Int {
    guard let n = Int(s) else {
        throw ParseError.invalid
    }
    return n
}

func safeParse(_ s: String) -> Int {
    do {
        return try parse(s)
    } catch {
        return 0
    }
}

